/**
 * Rate limits before a session exists have no tenant. The sentinel prefix
 * keeps each address on the free-plan bucket shape, and the address itself
 * (lower-cased) is part of the key so one account cannot lock out another.
 */
const ANONYMOUS_ORG = "00000000000000000000000000" as OrgId;

function rateLimitOrgForAddress(email: string): OrgId {
  return `${ANONYMOUS_ORG}:${email.toLowerCase()}` as OrgId;
}

function rateLimitOrgForResetConfirm(token: string): OrgId {
