import { afterAll, beforeAll, describe, expect, it, vi } from "vitest";
import { getBucketConfig, resetRateLimits } from "@/lib/rate-limit";
import { toIsoTimestamp } from "@/types/common";
import { useTemporaryDatabase } from "../server/_support/fixtures";
import { purgeExpiredSessions } from "@/server/repositories/session-repository";
import {
  confirmPasswordReset,
  login,
  register,
  requestPasswordReset,
} from "@/server/services/auth-service";
import { loginAction } from "@/actions/auth/login";
import { requestPasswordResetAction } from "@/actions/auth/reset-password";
import {
  destroySession,
  resolveSession,
} from "@/server/services/session-service";

const emails = vi.hoisted(
  () => [] as { to: string; subject: string; html: string }[],
);

vi.mock("@/server/services/email-service", async () => {
  const actual = await vi.importActual<
    typeof import("@/server/services/email-service")
  >("@/server/services/email-service");
  return {
    ...actual,
    sendEmail: vi.fn(
      async (message: { to: string; subject: string; html: string }) => {
        emails.push(message);
      },
    ),
  };
});

const HOUR = 60 * 60 * 1000;
const DAY = 24 * HOUR;
const START = new Date("2026-06-01T00:00:00.000Z");
const PASSWORD = "OldPassword123";
const NEXT_PASSWORD = "NewPassword123";

function resetTokensFor(address: string): string[] {
  return emails
    .filter(
      (message) =>
        message.to === address.toLowerCase() &&
        message.subject.startsWith("Reset your Taskflow password"),
    )
    .map((message) => {
      const match = message.html.match(/<td>token<\/td><td>([^<]+)<\/td>/);
      if (!match?.[1]) throw new Error("reset email had no token");
      return match[1];
    });
}

describe("auth session fixes", () => {
  let cleanup: () => void;

  beforeAll(async () => {
    cleanup = await useTemporaryDatabase();
    vi.useFakeTimers({ toFake: ["Date"] });
    vi.setSystemTime(START);
    await register({
      name: "Ada Lovelace",
      email: "Ada@Example.com",
      password: PASSWORD,
      confirmPassword: PASSWORD,
      acceptTerms: true,
    });
    await register({
      name: "Grace Hopper",
      email: "grace@example.com",
      password: PASSWORD,
      confirmPassword: PASSWORD,
      acceptTerms: true,
    });
  });

  afterAll(() => {
    vi.useRealTimers();
    cleanup();
  });

  it("keeps sign-out, remember-me and reset links scoped to one account", async () => {
    resetRateLimits();
    emails.length = 0;
    vi.setSystemTime(START);

    const adaShort = await login({
      email: "ADA@example.com",
      password: PASSWORD,
      rememberMe: false,
    });
    const adaLong = await login({
      email: "ada@example.com",
      password: PASSWORD,
      rememberMe: true,
    });
    const grace = await login({
      email: "grace@example.com",
      password: PASSWORD,
      rememberMe: false,
    });

    const shortPrincipal = await resolveSession(adaShort.token);
    const longPrincipal = await resolveSession(adaLong.token);
    expect(shortPrincipal).not.toBeNull();
    expect(longPrincipal).not.toBeNull();
    expect(new Date(shortPrincipal!.expiresAt).getTime()).toBe(
      START.getTime() + DAY,
    );
    expect(new Date(longPrincipal!.expiresAt).getTime()).toBe(
      START.getTime() + 30 * DAY,
    );

    await destroySession(adaShort.token);
    await destroySession(adaShort.token);
    await destroySession("not-a-session");
    expect(await resolveSession(adaShort.token)).toBeNull();
    expect(await resolveSession(adaLong.token)?.userId).toBe(
      longPrincipal!.userId,
    );
    expect(await resolveSession(grace.token)?.email).toBe("grace@example.com");

    const again = await login({
      email: "ada@example.com",
      password: PASSWORD,
      rememberMe: false,
    });
    expect(await resolveSession(again.token)).not.toBeNull();

    expect(
      await purgeExpiredSessions(toIsoTimestamp(new Date(START.getTime() + HOUR))),
    ).toBe(0);
    vi.setSystemTime(new Date(START.getTime() + DAY));
    expect(
      await purgeExpiredSessions(toIsoTimestamp(new Date(START.getTime() + DAY))),
    ).toBeGreaterThan(0);
    expect(await resolveSession(again.token)).toBeNull();
    expect(await resolveSession(adaLong.token)).not.toBeNull();
    expect(await resolveSession(grace.token)).toBeNull();

    vi.setSystemTime(new Date(START.getTime() + 30 * DAY));
    expect(await resolveSession(adaLong.token)).toBeNull();

    vi.setSystemTime(START);
    resetRateLimits();
    emails.length = 0;

    await requestPasswordReset({ email: "nobody@example.com" });
    expect(resetTokensFor("nobody@example.com")).toHaveLength(0);

    await requestPasswordReset({ email: "Ada@Example.com" });
    await requestPasswordReset({ email: "GRACE@example.com" });
    const adaFirst = resetTokensFor("ada@example.com")[0]!;
    const graceFirst = resetTokensFor("grace@example.com")[0]!;

    await requestPasswordReset({ email: "ada@example.com" });
    const adaSecond = resetTokensFor("ada@example.com")[1]!;

    await expect(
      confirmPasswordReset({
        token: adaFirst,
        password: NEXT_PASSWORD,
        confirmPassword: NEXT_PASSWORD,
      }),
    ).rejects.toThrow(/no longer valid/);

    vi.setSystemTime(new Date(START.getTime() + 59 * 60 * 1000));
    const adaSession = await login({
      email: "ada@example.com",
      password: PASSWORD,
      rememberMe: true,
    });
    const graceSession = await login({
      email: "grace@example.com",
      password: PASSWORD,
      rememberMe: false,
    });

    const resetAda = await confirmPasswordReset({
      token: adaSecond,
      password: NEXT_PASSWORD,
      confirmPassword: NEXT_PASSWORD,
    });
    expect(resetAda.email).toBe("ada@example.com");
    expect(await resolveSession(adaSession.token)).toBeNull();
    expect(await resolveSession(graceSession.token)).not.toBeNull();

    await expect(
      confirmPasswordReset({
        token: adaSecond,
        password: "OtherPassword123",
        confirmPassword: "OtherPassword123",
      }),
    ).rejects.toThrow(/no longer valid/);

    await expect(
      login({
        email: "ada@example.com",
        password: PASSWORD,
        rememberMe: false,
      }),
    ).rejects.toThrow(/did not match/);
    const adaNew = await login({
      email: "ADA@example.com",
      password: NEXT_PASSWORD,
      rememberMe: false,
    });
    expect(await resolveSession(adaNew.token)).not.toBeNull();

    await confirmPasswordReset({
      token: graceFirst,
      password: NEXT_PASSWORD,
      confirmPassword: NEXT_PASSWORD,
    });

    vi.setSystemTime(START);
    resetRateLimits();
    emails.length = 0;
    await requestPasswordReset({ email: "ada@example.com" });
    const expiring = resetTokensFor("ada@example.com").at(-1)!;
    vi.setSystemTime(new Date(START.getTime() + 60 * 60 * 1000));
    await expect(
      confirmPasswordReset({
        token: expiring,
        password: "ExpiredPassword1",
        confirmPassword: "ExpiredPassword1",
      }),
    ).rejects.toThrow(/no longer valid/);
  });

  it("limits sign-in and reset requests per address", async () => {
    resetRateLimits();
    emails.length = 0;
    vi.setSystemTime(START);

    const loginCapacity = getBucketConfig("auth:login").capacity;
    let blockedAt = 0;
    for (let attempt = 1; attempt <= loginCapacity + 5; attempt += 1) {
      try {
        await login({
          email: "Ada@Example.com",
          password: "wrong-password",
          rememberMe: false,
        });
      } catch (error) {
        const message = error instanceof Error ? error.message : "";
        if (message.includes("Too many sign-in attempts")) {
          blockedAt = attempt;
          break;
        }
        expect(message).toMatch(/did not match/);
      }
    }
    expect(blockedAt).toBe(loginCapacity + 1);

    await expect(
      login({
        email: "ada@example.com",
        password: NEXT_PASSWORD,
        rememberMe: false,
      }),
    ).rejects.toThrow(/Too many sign-in attempts/);

    const graceWhileAdaLocked = await login({
      email: "grace@example.com",
      password: NEXT_PASSWORD,
      rememberMe: false,
    });
    expect(graceWhileAdaLocked.token).toBeTruthy();

    const beforeReset = emails.length;
    await requestPasswordReset({ email: "ADA@example.com" });
    expect(emails.length).toBe(beforeReset + 1);
    const token = resetTokensFor("ada@example.com").at(-1)!;
    await confirmPasswordReset({
      token,
      password: "ResetWhileLocked1",
      confirmPassword: "ResetWhileLocked1",
    });

    vi.setSystemTime(new Date(START.getTime() + 60 * 1000));
    const recovered = await login({
      email: "ada@example.com",
      password: "ResetWhileLocked1",
      rememberMe: false,
    });
    expect(recovered.token).toBeTruthy();

    resetRateLimits();
    emails.length = 0;
    vi.setSystemTime(START);
    const resetCapacity = getBucketConfig("auth:password-reset").capacity;
    for (let attempt = 0; attempt < resetCapacity; attempt += 1) {
      await requestPasswordReset({ email: "Grace@Example.com" });
    }
    const graceSent = resetTokensFor("grace@example.com").length;
    await requestPasswordReset({ email: "grace@example.com" });
    expect(resetTokensFor("grace@example.com")).toHaveLength(graceSent);

    await requestPasswordReset({ email: "ada@example.com" });
    expect(resetTokensFor("ada@example.com").length).toBeGreaterThan(0);

    const graceStillSignsIn = await login({
      email: "grace@example.com",
      password: "ResetWhileLocked1",
      rememberMe: false,
    });
    expect(graceStillSignsIn.token).toBeTruthy();

    const adaAction = await loginAction({
      email: "ada@example.com",
      password: "wrong-password",
      rememberMe: false,
    });
    const graceAction = await loginAction({
      email: "grace@example.com",
      password: "wrong-password",
      rememberMe: false,
    });
    expect(adaAction.ok).toBe(false);
    expect(graceAction.ok).toBe(false);
    if (!adaAction.ok && !graceAction.ok) {
      expect(adaAction.error.message).toMatch(/did not match/);
      expect(graceAction.error.message).toMatch(/did not match/);
    }

    const adaReset = await requestPasswordResetAction({
      email: "ada@example.com",
    });
    const graceReset = await requestPasswordResetAction({
      email: "nobody-else@example.com",
    });
    expect(adaReset.ok).toBe(true);
    expect(graceReset.ok).toBe(true);
  }, 120_000);
});

